'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

let p = 0;
const N = Number(input[p++]);
const M = Number(input[p++]);
const grid = Array.from({ length: N }, () => input[p++].split(''));

const queue = [];
for (let r = 0; r < N; r++) {
  for (let c = 0; c < M; c++) {
    if (grid[r][c] === 'o') queue.push(r * M + c);
  }
}

for (let head = 0; head < queue.length; head++) {
  const pos = queue[head];
  const r = Math.floor(pos / M);
  const c = pos % M;

  if (r + 1 < N && grid[r + 1][c] === '.') {
    grid[r + 1][c] = 'o';
    queue.push((r + 1) * M + c);
  }

  if (r + 1 < N && grid[r + 1][c] === '#') {
    if (c > 0 && grid[r][c - 1] === '.') {
      grid[r][c - 1] = 'o';
      queue.push(r * M + c - 1);
    }
    if (c + 1 < M && grid[r][c + 1] === '.') {
      grid[r][c + 1] = 'o';
      queue.push(r * M + c + 1);
    }
  }
}

console.log(grid.map(row => row.join('')).join('\n'));
